export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const [picked, setPicked] = React.useState({});
  const [methodChanged, setMethodChanged] = React.useState(false);
  const list = v => Array.isArray(v) ? v : [];
  const text = v => v === null || v === undefined || v === '' ? 'Unknown' : typeof v === 'object' ? JSON.stringify(v) : String(v);
  const label = v => ({original_payment:'Original payment method',store_credit:'Store credit',print_label:'Print a shipping label',qr_dropoff:'Printer-free QR drop-off'}[v] || text(v));
  const money = v => {
    if (typeof v !== 'number' || !Number.isFinite(v) || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US', {style:'currency',currency:m.currency}).format(v / 100); } catch (e) { return 'Unknown currency'; }
  };
  const initial = !task || t.status === 'not_started';
  const locked = initial || !!t.progress || ['working','created','submitting'].includes(t.status) || !!t.receipt || typeof act !== 'function';
  const methods = list(m.methods).filter(x => x && ['print_label','qr_dropoff'].includes(x.value));
  const reasons = list(m.reasons).filter(x => x && x.value);
  const chosenMethod = picked.method || m.method || '';
  const chosenReason = picked.reason !== undefined ? picked.reason : t.reason || '';
  const wantedDestination = intent.refundDestination || 'original_payment';
  const lines = list(m.lines);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines.map(x => typeof x === 'object' && x ? x.id : x) : null;
  const failedChecks = list(t.checks).filter(c => c && (['fail','failed','conflict','mismatch','error'].includes(c.status) || (c.expected !== undefined && c.observed !== undefined && JSON.stringify(c.expected) !== JSON.stringify(c.observed))));
  const destinationConflict = !!m.refundDestination && m.refundDestination !== wantedDestination;
  const methodConflict = !!m.method && ((chosenMethod && chosenMethod !== m.method) || (intent.noPrinter !== false && m.method === 'print_label'));
  const badLines = selected && lines.some(x => selected.includes(x.id) && !/red.*(shoe|running)|(shoe|running).*red/i.test(x.name || ''));
  const conflicts = destinationConflict || methodConflict || badLines || failedChecks.length > 0;
  const fallbackScreens = [
    {id:'01M5R73NT08XXCVGVY7X7S1M2P',name:'Your next chapter, outside. | Northstar Outfitters'},
    {id:'01M5R742D3KSREFCGXJB6T13PP',name:'Your orders | Northstar Outfitters'},
    {id:'01M5R74H4C80FFNPT6PV15Q9GE',name:'Shop the collection | Northstar Outfitters'}
  ];
  const fallbackFlows = [
    {id:'01M5R7451Y26PZWSB16W15RRKY',name:'My orders',exit:'01M5R742D3KSREFCGXJB6T13PP',status:'verified'},
    {id:'01M5R74ZPWYKEJK4F9MJF7DRRS',name:'View orders & delivery',exit:'01M5R73NT08XXCVGVY7X7S1M2P',status:'verified'},
    {id:'01M5R73RHDGTV5P3C6CKD2K7JK',name:'View product & options →',exit:'01M5R73NT08XXCVGVY7X7S1M2P',status:'verified'},
    {id:'01M5R74MA6GG4HDB9T2VNW75HB',name:'Browse all products',exit:'01M5R74H4C80FFNPT6PV15Q9GE',status:'verified'}
  ];
  const discovery = t.discovery || {};
  const screens = list(discovery.screens).length ? discovery.screens : fallbackScreens;
  const flows = list(discovery.flows).length ? discovery.flows : fallbackFlows;
  const orderedFlows = [...flows].sort((a,b) => Number(/order/i.test(b.name || '')) - Number(/order/i.test(a.name || '')));
  const choose = (key, value) => {
    if (locked || !value) return;
    setPicked(prev => ({...prev, [key]:value}));
    if (key === 'method') setMethodChanged(true);
    act('choice', {[key]:value});
  };
  const statusCopy = t.receipt ? 'The host has supplied a receipt. Review the separate saved-confirmation verification below.' : t.error ? 'An error needs attention. No completion is claimed.' : t.progress ? 'Updating source information. Controls are temporarily unavailable.' : initial ? 'Not started. Review the supported task before using the host’s Start this task control.' : ['working','created','submitting'].includes(t.status) ? 'The host is processing this task. Controls are temporarily unavailable.' : conflicts ? 'Your choices and the observed source do not match. Restore your choices, then validate.' : 'Review the current source terms, then validate. Validation does not submit the return.';
  return <main className="generated-root">
    <header className="generated-header"><span className="generated-brand">Northstar Outfitters</span><span className="generated-sandbox">Sandbox · synthetic records only</span></header>
    <div className="generated-content">
      <p className="generated-eyebrow">Your return, on your terms</p>
      <h1>Return your red shoes</h1>
      <p className="generated-intro">No printer. Keep the jacket. Refund your original payment method.</p>
      <section className="generated-status" role="status" aria-live="polite" aria-atomic="true"><strong>{initial ? 'Task overview' : 'Live task status'}</strong><p>{statusCopy}</p>{t.status && <span className="generated-small">Host state: {text(t.status)}</span>}</section>
      {t.error && <section className="generated-warning" role="alert"><h2>Source error</h2><p>{text(t.error)}</p></section>}
      {initial ? <>
        <section className="generated-panel"><p className="generated-eyebrow">Supported task</p><h2>Return only the red shoes</h2><ul className="generated-goals"><li>Keep jacket — not included in this return.</li><li>Use a printer-free method.</li><li>Preserve original-payment preference.</li></ul><p>The host provides <strong>Start this task</strong>. Starting prepares a synthetic draft; exact approval and submission are handled separately by the host.</p></section>
        <section className="generated-panel"><h2>What the source observations establish</h2><p>The printed-label draft and the QR drop-off draft both showed only the shoes selected, with the jacket kept. The printed-label route requires a printer. The QR route is printer-free and has a deduction.</p><p className="generated-warning generated-inline">Important dependency: changing to QR drop-off changed the observed refund destination to store credit. Your preference stays original payment. Check the live destination after any method change.</p><p>Current fees and refund amounts will appear from the live task data after starting. The observations are draft states, not completed returns.</p></section>
        <section className="generated-panel"><h2>Observed routes</h2><p className="generated-muted">Order routes are shown first for this return. These are reached screens, not proof that a return was completed.</p><div className="generated-route-grid">{orderedFlows.map((f,i) => {
          const reached = (f.currentObservation && f.currentObservation.reached) || f.exit;
          const screen = screens.find(s => s.id === reached);
          return <section className="generated-route" key={f.id || i}><h3>{text(f.name)}</h3><p><strong>Reached:</strong> {screen ? text(screen.name) : 'Unknown reached screen'}</p><p className="generated-small">Recorded status: {text(f.status)} · informational only</p></section>;
        })}</div><p className="generated-small">Exploration was incomplete because its budget ended. The red-shoes product path was not reached, and a source exception was recorded. The return-draft observations above provide separate evidence; no saved confirmation was observed.</p></section>
      </> : <>
        <div className="generated-grid">
          <div>
            <section className="generated-panel"><p className="generated-eyebrow">01 · Items</p><h2>Return shoes. Keep jacket.</h2><p className="generated-muted">Your requested scope is fixed here. There is no control to add the jacket.</p>{lines.length ? <ul className="generated-items">{lines.map((line,i) => <li key={line.id || i}><div><strong>{text(line.name)}</strong>{line.variant && <p className="generated-small">{text(line.variant)}</p>}<p className="generated-small">Source selection: {selected === null ? 'Unknown' : selected.includes(line.id) ? 'Included in return' : 'Not included'}</p></div><span className="generated-pill">{/jacket/i.test(line.name || '') ? 'Keep jacket' : /red.*(shoe|running)|(shoe|running).*red/i.test(line.name || '') ? 'Return requested' : 'Not requested'}</span></li>)}</ul> : <p>Source items: Unknown. Validate to read the current selection.</p>}{selected !== null && <p className="generated-small">Observed selected line IDs: {selected.length ? selected.map(text).join(', ') : 'None'}</p>}</section>
            <section className="generated-panel"><p className="generated-eyebrow">02 · Your choices</p><h2>How to return the shoes</h2><div className="generated-field"><label htmlFor="generated-reason">Return reason</label><select id="generated-reason" disabled={locked || !reasons.length} value={chosenReason} onChange={e => choose('reason',e.target.value)}><option value="">Choose a reason</option>{chosenReason && !reasons.some(r => r.value === chosenReason) && <option value={chosenReason}>{text(chosenReason)}</option>}{reasons.map(r => <option key={r.value} value={r.value}>{r.label || r.value}</option>)}</select>{!reasons.length && <p className="generated-small">Available reasons are unknown.</p>}</div>
              <div className="generated-field"><label htmlFor="generated-method">Return method</label><select id="generated-method" disabled={locked || !methods.length} value={chosenMethod} onChange={e => choose('method',e.target.value)}><option value="">Choose a method</option>{chosenMethod && !methods.some(x => x.value === chosenMethod) && <option value={chosenMethod}>{label(chosenMethod)}</option>}{methods.map(x => <option key={x.value} value={x.value}>{x.label || label(x.value)}</option>)}</select><p className="generated-small">Selected choice: {chosenMethod ? label(chosenMethod) : 'Unknown'}</p><p className="generated-small">Currently observed source method: {label(m.method)}</p>{methods.find(x => x.value === chosenMethod)?.detail && <p className="generated-small">{text(methods.find(x => x.value === chosenMethod).detail)}</p>}</div>
              <p className="generated-note">A method change can alter the source refund destination. Your original-payment preference is not changed with it.</p>{methodChanged && <p className="generated-warning generated-inline">Method choice changed. Compare the current source destination and deduction, then validate again.</p>}
              <div className="generated-preference"><strong>Refund preference</strong><p>{label(wantedDestination)}</p><span className="generated-small">Preserved as your intent; not an editable source value.</span></div>
            </section>
          </div>
          <section className="generated-panel generated-review"><p className="generated-eyebrow">03 · Source review</p><h2>Current return terms</h2><p className="generated-muted">Observed source values, not a guarantee of completion.</p><dl className="generated-terms"><div><dt>Return method</dt><dd>{label(m.method)}</dd></div><div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div><div><dt>Refund destination</dt><dd>{label(m.refundDestination)}</dd></div><div className="generated-total"><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div></dl>{(m.deductionCents == null || m.expectedRefundCents == null || !m.currency || !m.refundDestination || selected === null) && <p className="generated-warning generated-inline">Some source terms are unknown. They must be established before exact approval can proceed.</p>}<p className="generated-small">No real shipment, QR code or refund is created in this sandbox.</p></section>
        </div>
        {conflicts && <section className="generated-warning" role="alert"><h2>Source conflict — review before continuing</h2>{destinationConflict && <p><strong>Requested:</strong> {label(wantedDestination)}<br/><strong>Observed:</strong> {label(m.refundDestination)}</p>}{methodConflict && <p><strong>Requested:</strong> {picked.method ? label(picked.method) : 'Printer-free return'}<br/><strong>Observed:</strong> {label(m.method)}</p>}{badLines && <p>The source includes an item outside the requested red-shoes-only return. Keep the jacket.</p>}{failedChecks.map((c,i) => <div className="generated-check" key={i}><strong>{text(c.label)}</strong><p>Requested: {text(c.expected)}<br/>Observed: {text(c.observed)}</p></div>)}<p>Restoring reapplies your choices; it does not submit a return.</p><button className="generated-secondary" type="button" disabled={locked} onClick={() => act('check',{repair:true})}>Restore my choices</button></section>}
        <section className="generated-panel"><h2>Validate before exact approval</h2><p>Check the source selection, printer-free method, deduction and original-payment destination. The host will separately ask you to approve exact current terms and verify the saved confirmation.</p>{list(t.checks).length > 0 && <ul className="generated-checks">{list(t.checks).map((c,i) => <li key={i}><strong>{text(c.label)}</strong><span>{text(c.status)}</span><p>Expected: {text(c.expected)}<br/>Observed: {text(c.observed)}</p></li>)}</ul>}<div className="generated-actions"><button className="generated-primary" type="button" disabled={locked} onClick={() => act('check',{repair:false})}>Validate current choices</button>{!conflicts && <button className="generated-secondary" type="button" disabled={locked} onClick={() => act('check',{repair:true})}>Restore my choices</button>}</div><p className="generated-small">Validation is not submission. A saved draft is not a completed return.</p></section>
        {t.receipt && <section className="generated-panel"><h2>Receipt supplied by host</h2><p>See the host’s receipt and independent saved-confirmation result for the final outcome. Editing and validation are now disabled.</p></section>}
      </>}
      <footer className="generated-footer">Synthetic records only · No production access · Exact approval and final confirmation stay with the trusted host.</footer>
    </div>
  </main>;
}
